const CACHE='astro-kitty-offline-v19';
const FILES=['./','./index.html','./styles.css','./app.js','./art.js','./story.js','./launch.js','./launch-engine.js','./story-engine.js','./story-training.js','./surface-world.js','./story-controls.js','./story-sound.js','./resources.js','./audio/sfx/manifest.json','./engine.js','./icon.svg','./base-design.js','./landing-sites.js','./mission-link.js','./outpost-setup.js','./assets/mars-viking.jpg','./journey.js','./flags.js','./compat.js','./strings.js','./outpost.html','./outpost.css','./outpost.js','./outpost-engine.js','./nasa-data.js','./mission-code.js','./solar-archive.js','./outpost-presentation.js','./data/DONKI_SOURCES.md','./data/donki-events.json','./teacher.html','./teacher.js','./classic/','./classic/index.html','./classic/app.js','./classic/engine.js','./classic/field-engine.js','./classic/field-training.js','./classic/field-art.js','./classic/field-training.css','./classic/styles.css','./classic/icon.svg'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(async()=>{try{const r=await fetch(new URL('./audio/sfx/manifest.json',self.location.href));if(r.ok){const data=await r.json(),cache=await caches.open(CACHE);for(const file of data.files??[])if(['yay.mp3','applause.mp3','meow.mp3','purr.mp3'].includes(file)){try{await cache.add('./audio/sfx/'+file);}catch{}}}}catch{}return self.skipWaiting();})));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('astro-kitty-offline-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{
  const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==location.origin)return;

  event.respondWith(fetch(event.request).then(response=>{if(response.ok&&response.type==='basic'){const copy=response.clone();caches.open(CACHE).then(cache=>cache.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request,{ignoreSearch:event.request.mode==='navigate'}).then(cached=>cached||new Response('',{status:503}))));
});
